ase_id;\n\n    -- 6. Audit\n    INSERT INTO app.case_audit(\n        case_id,\n        action,\n        actor_id,\n        old_status,\n        new_status,\n        correlation_id\n    )\n    VALUES (\n        p_case_id,\n        p_action,\n        p_actor_id,\n        v_current_status,\n        p_target_status,\n        current_setting('app.correlation_id', true)\n    );\n\n    -- 7. Outbox\n    INSERT INTO app.outbox_event(\n        aggregate_type,\n        aggregate_id,\n        event_type,\n        payload\n    )\n    VALUES (\n        'case',\n        p_case_id,\n        'case.transitioned',\n        jsonb_build_object(\n            'case_id', p_case_id,\n            'action', p_action,\n            'old_status', v_current_status,\n            'new_status', p_target_status,\n            'actor_id', p_actor_id,\n            'correlation_id', current_setting('app.correlation_id', true)\n        )\n    )\n    RETURNING id INTO v_outbox_id;\n\n    -- 8. Wake up worker\n    PERFORM pg_notify('outbox_available', v_outbox_id::text);\n\n    RETURN p_case_id;\nEND;\n$$;\n"
